insert into public.dataset_licenses (dataset_id, license_code, tier, task_pack)
select id, 'KOJOH-TQQ-LIC-0029', 'standard', $pack${"phases": [{"key": "python", "title": "Phase 1, Python: Clean, Label and Build Features", "tasks": [{"id": "P4", "text": "Clean billing and tickets: status variants, amounts, timestamps, and the seven ticket categories."}, {"id": "P1", "text": "Load the four files and profile them. List every column in `customers_raw.csv` and mark it as known at signup, changes over time, or describes the export day. That third list is your leakage list."}, {"id": "P5", "text": "Build the population and the label for both cutoffs exactly as the setup defines them. Report the population size and churn rate for each."}, {"id": "P3", "text": "Clean usage: parse five month formats, convert `Watch_Hours` (`12.5`, `12.5 hrs`, `750 min`) to hours, cap impossible `Days_Active`, and keep only the latest `Batch_ID` where a month was restated. How many restated rows did you drop?"}, {"id": "P8", "text": "Prove the leakage. Train a quick model on the test window using `Days_Since_Last_Login` and `Customer_Health_Score`, report its AUC, then explain in two sentences why that number is fake."}, {"id": "P6", "text": "Build leak-free features at a cutoff: hours in each of the last four full months, a usage trend, days active last month, payment failures and tickets (all, buffering, cancel requests) in the last 90 days, tenure, plan, cycle, payment method, device, channel, promo, language, tier, profiles and age."}, {"id": "P2", "text": "Clean the customer table: Customer_ID formats across files (`cp100123`, `CP-100123`, leading spaces), five date formats, Age (`24 yrs`, `999`, blank), City spellings (Bangalore, Bombay, Calcutta, Gurgaon...), Plan and Billing_Cycle variants, and Price_INR text."}, {"id": "P7", "text": "Add the feature most people miss: whether the subscriber even **has a renewal date inside the window**. An annual subscriber renewing in June cannot churn in January to March. Count a renewal in the 10 days before the cutoff too, because a failed payment is still being retried then. What is the churn rate with and without one?"}]}, {"key": "sql", "title": "Phase 2, SQL and Modelling: Understand and Predict the Churn", "tasks": [{"id": "M4", "text": "**Your money:** with the offer at ₹99, a 35% save rate and 1000 calls, how many rupees does calling your top 1000 subscribers earn on the test window, and how does that compare with calling 1000 at random?"}, {"id": "M1", "text": "Baseline model: logistic regression on your leak-free features, trained on the October window and tested on the January window. Report AUC, PR AUC and the churn rate in the top 10% of scores."}, {"id": "M2", "text": "Try gradient boosting (LightGBM, XGBoost or scikit-learn) and compare it honestly with the baseline on the test window. Keep whichever wins, and show the five features that matter most."}, {"id": "S1", "text": "Churn rate by billing cycle, plan and payment method in the test window, with the population count behind each rate."}, {"id": "M3", "text": "Train the same model on a random 80/20 split of the test window and compare its AUC with your time-based number. Explain why the time-based number is the one you report, even if the two come out close."}, {"id": "S3", "text": "The FIRST99 promo: churn at the first full price renewal for promo subscribers against everyone else."}, {"id": "S5", "text": "Churn rate by language and tier. Which languages lose subscribers fastest, and is it about the catalogue?"}, {"id": "S2", "text": "Split churn into voluntary and involuntary (renewal payment failed twice and was never recovered). What share of churners never chose to leave, and which payment methods cause it?"}, {"id": "S6", "text": "Tickets: churn rate for subscribers with a buffering ticket or a cancel request in the 90 days before the cutoff, against those without."}, {"id": "S7", "text": "Using window functions, compute each subscriber's month on month change in watch hours and the number of consecutive declining months before the cutoff."}, {"id": "S4", "text": "Usage before churn: average watch hours in each of the 6 months before churn, separately for voluntary and involuntary churners, against subscribers who stayed. When does the fade start, and who does not fade at all?"}, {"id": "S8", "text": "**Your segment, Smart TV viewers:** population, churners, churn rate and involuntary share in the test window, and the monthly revenue those churners took with them."}]}, {"key": "dash1", "title": "Phase 3a, Dashboard Page 1: Subscriber and Call List", "tasks": [{"id": "D2", "text": "Show the top reasons behind that score (SHAP values, or the features with the biggest effect)."}, {"id": "D4", "text": "Add filters for plan, cycle, payment method, language and tier that also drive the call list."}, {"id": "D3", "text": "Add a call list: the 1000 highest scored subscribers in the test window, with monthly revenue and the reason to call."}, {"id": "D5", "text": "Mark involuntary risk separately: subscribers whose last renewal failed at least once."}, {"id": "D1", "text": "Build a subscriber lookup: type a Customer_ID and see the profile, the monthly usage line, bills and tickets on one timeline, and the model's churn score at the test cutoff."}]}, {"key": "dash2", "title": "Phase 3b, Dashboard Page 2: Model and Money", "tasks": [{"id": "D11", "text": "Voluntary against involuntary churn by month and payment method."}, {"id": "D13", "text": "A segment page for Smart TV viewers."}, {"id": "D8", "text": "A profit curve: rupees gained for every call list size from 0 to the whole population, using your offer cost and success rate, with your capacity marked."}, {"id": "D6", "text": "Model page header: AUC, PR AUC, base rate and the lift in the top 10% on the test window."}, {"id": "D10", "text": "The fade: average hours in the months before churn against stayers."}, {"id": "D15", "text": "Make every panel respect the segment filters."}, {"id": "D12", "text": "Feature importance for the final model, with leaky features shown greyed out as excluded."}, {"id": "D7", "text": "A calibration chart: predicted against actual churn by score decile."}, {"id": "D14", "text": "A threshold slider that updates precision, recall, calls made and rupees gained."}, {"id": "D9", "text": "Churn rate by cycle, plan, payment method, language and tier, all in one view."}]}, {"key": "documentation", "title": "Phase 4, Documentation", "tasks": [{"id": "DOC1", "text": "Write a model card plus a business memo. The model card covers data, population, label, leakage you removed, features, validation and test results. The memo, for the head of growth, says how many people to call, who, and what it is worth in rupees with an offer of ₹99 saving 35% of churners, and what to do about involuntary churn, which a phone call will not fix."}]}, {"key": "stretch", "title": "Stretch ideas (optional)", "tasks": [{"id": "X-S2", "text": "Estimate how much revenue would be saved by retrying failed renewals on day 1, 3 and 7 instead of only day 3."}, {"id": "X-S3", "text": "Is the FIRST99 promo worth it? Compare 12 month revenue per subscriber with and without it."}, {"id": "X-S1", "text": "Build a separate model for involuntary churn using only payment history, and compare it with the main model on those churners."}]}], "brief": "**Your business brief (shared with 4 other buyers):** segment **Smart TV viewers**, offer cost **₹99**, save rate **35%**, call capacity **1000**."}$pack$::jsonb
from public.datasets where slug = 'the-quiet-quitters-ott-churn'
on conflict (license_code) do nothing;

